arguments.command:
cat >/tmp/choose.pl <<'PL'
use strict; use warnings;
sub rc { my $s=reverse shift; $s =~ tr/acgtACGT/tgcaTGCA/; return lc $s }
open my $fh,'<','/app/sequences.fasta' or die $!; my(%r,$n); while(<$fh>){chomp; if(/^>(.*)/){$n=$1;$r{$n}=''} else {$r{$n}.=lc $_}}
my %b=(input=>[691,210],egfp=>[4,714],flag=>[7,87],snap=>[7,546]);
for my $k(qw(input egfp flag snap)){
 my($fs,$re)=@{$b{$k}}; my @f; my @rv;
 for my $l(15..36){
  my $f=substr($r{$k},$fs,$l); my $tm=`oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $f`; chomp $tm; push @f,[$l,$tm,$f] if $tm>=58&&$tm<=72;
  my $x=rc(substr($r{$k},$re-$l,$l)); $tm=`oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $x`; chomp $tm; push @rv,[$l,$tm,$x] if $tm>=58&&$tm<=72;
 }
 my @pairs; for my $f(@f){for my $v(@rv){my $d=abs($f->[1]-$v->[1]); next if $d>5; my $score=abs($f->[1]-65)+abs($v->[1]-65)+0.10*abs($f->[0]-$v->[0]); push @pairs,[$score,$d,$f,$v]}}
 @pairs=sort {$a->[0]<=>$b->[0]} @pairs;
 print "\n$k forward boundary $fs reverse boundary $re\n";
 for my $x(@pairs[0..($#pairs<7?$#pairs:7)]){ printf "score %.2f diff %.3f F%d %.3f %s | R%d %.3f %s\n",@$x[0,1],$x->[2][0],$x->[2][1],$x->[2][2],$x->[3][0],$x->[3][1],$x->[3][2] }
}
PL
perl /tmp/choose.pl

cat >/tmp/validate.pl <<'PL'
use strict; use warnings;
sub rc { my $s=reverse shift; $s =~ tr/acgt/tgca/; return lc $s }
open my $fh,'<','/app/sequences.fasta' or die $!; my(%r,$n); while(<$fh>){chomp; if(/^>(.*)/){$n=$1;$r{$n}=''} else {$r{$n}.=lc $_}}
my %cfg=(
 input=>{fstart=>691,rend=>210,fo=>'taat',ro=>'tcat',fl=>20,rl=>36},
 egfp=>{fstart=>4,rend=>714,fo=>'atga',ro=>'tacc',fl=>17,rl=>21},
 flag=>{fstart=>7,rend=>87,fo=>'ggta',ro=>'tgtc',fl=>18,rl=>24},
 snap=>{fstart=>7,rend=>546,fo=>'gaca',ro=>'atta',fl=>21,rl=>18},
);
my %p; my $clamp='ggctac'; my $tail=$clamp.'ggtctc'.'c';
for my $k(qw(input egfp flag snap)){
 my$c=$cfg{$k};
 my $fa=substr($r{$k},$c->{fstart},$c->{fl});
 my $ra=rc(substr($r{$k},$c->{rend}-$c->{rl},$c->{rl}));
 $p{"$k.fwd"}=$tail.$c->{fo}.$fa;
 $p{"$k.rev"}=$tail.$c->{ro}.$ra;
 my $tf=`oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $fa`;chomp$tf;
 my $tr=`oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $ra`;chomp$tr;
 printf "%s F %s anneal=%d nt Tm=%.3f primer=%s\n",$k,$c->{fo},length($fa),$tf,$p{"$k.fwd"};
 printf "%s R %s anneal=%d nt Tm=%.3f primer=%s\n",$k,$c->{ro},length($ra),$tr,$p{"$k.rev"};
 printf "pair diff=%.3f\n",abs($tf-$tr);
 die "bad exact anneal" unless $fa eq substr($r{$k},$c->{fstart},$c->{fl}) && $ra eq rc(substr($r{$k},$c->{rend}-$c->{rl},$c->{rl}));
}
for my$k(qw(input egfp flag snap output)){
 my@sites; while($r{$k}=~/(ggtctc|gagacc)/g){push@sites,$1.'@'.($-[0]+1)} print "$k BsaI-related sites: ",@sites?join(',',@sites):'none',"\n";
}
my $back=substr($r{input},687,4).substr($r{input},691).substr($r{input},0,210);
my $eg=substr($r{egfp},0,4).substr($r{egfp},4,710);
my $fl=substr($r{flag},3,84);
my $sn=substr($r{snap},0,3); # intentionally not used
$sn=substr($r{snap},3,543);
my $assembled=$back; # final circle starting at input origin is prefix+insert+suffix, not fragment order
my $out_expected=substr($r{input},0,210).substr($r{egfp},0,714).substr($r{flag},3,84).substr($r{snap},3,543).substr($r{input},687);
print "fragment lengths back/egfp/flag/snap: ",join('/',map length,($back,$eg,$fl,$sn)),"\n";
print "reconstructed target exact: ",($out_expected eq $r{output}?'YES':'NO')," len ",length($out_expected),"\n";
print "output len ",length($r{output}),"\n";
PL
perl /tmp/validate.pl

cat >/tmp/finalcheck.pl <<'PL'
use strict; use warnings;
sub rc { my $s=reverse shift; $s =~ tr/acgtACGT/tgcaTGCA/; lc $s }
open my $sf,'<','/app/sequences.fasta' or die $!; my(%r,$n); while(<$sf>){chomp; if(/^>(.*)/){$n=$1;$r{$n}=''}else{$r{$n}.=lc $_}}
open my $pf,'<','/app/primers.fasta' or die $!; my(%p,$h,$blank,$bad); while(<$pf>){chomp; if($_ eq ''){$blank++} elsif(/^>(\S+)$/){$h=$1} elsif(/^[ACGT]+$/i && $h){$p{$h}=lc $_} else {$bad++}}
my %c=(input=>[691,210,'taat','tcat',20,36],egfp=>[4,714,'atga','tacc',17,21],flag=>[7,87,'ggta','tgtc',18,24],snap=>[7,546,'gaca','atta',21,18]);
my $ok=1; print "headers/sequences: ",scalar(keys%p),"\n"; print "blank_lines=",($blank||0)," malformed_lines=",($bad||0),"\n";
for my $k(qw(input egfp flag snap)){my($fs,$re,$fo,$ro,$fl,$rl)=@{$c{$k}};for my $d(qw(fwd rev)){my$id="${k}_$d";my$tail=substr($p{$id},0,17);my$anneal=substr($p{$id},17);my$expected=$d eq'fwd'?substr($r{$k},$fs,$fl):rc(substr($r{$k},$re-$rl,$rl));my$tm=`oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $anneal`;chomp$tm;printf "%s %2d nt %.3f C\n",$id,length($anneal),$tm; $ok=0 if length($anneal)<15||length($anneal)>45||$tm<58||$tm>72||$anneal ne $expected||$tail ne 'ggctacggtctcc';} my$tf=`oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 `.substr($p{"${k}_fwd"},17);chomp$tf;my$tr=`oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 `.substr($p{"${k}_rev"},17);chomp$tr;printf "%s pair diff %.3f C\n",$k,abs($tf-$tr);$ok=0 if abs($tf-$tr)>5;}
$ok=0 unless scalar(keys%p)==8;
print $ok?"FINAL CHECK: PASS\n":"FINAL CHECK: FAIL\n";
PL
perl /tmp/finalcheck.pl
printf 'blank line numbers: '; grep -n '^$' /app/primers.fasta || true
printf 'header count: '; grep -c '^>' /app/primers.fasta
printf 'sequence line count: '; grep -vc '^>' /app/primers.fasta
printf 'file bytes: '; wc -c </app/primers.fasta

